    let mut a_sequence_bytes = vec![0_u8; gate_beta_sequence_bytes_len];
    let mut b_sequence_bytes = vec![0_u8; gate_beta_sequence_bytes_len];
    let mut z_sequence_bytes = vec![0_u8; hidden_sequence_bytes_len];
